<script setup lang="ts">
// 生产链记录详情：产品 → 工单 → 工序任务 → 逐笔报工 → 工艺路线 → BOM → 真实领退料。
// 迁自 liushanmen-v1/src/App.vue 的详情弹窗与核对记录弹窗；「记录解读」按钮去掉，打开详情即把对象设为右下角解读的当前对象。
import {computed,onMounted,ref} from 'vue'
import UButton from '@nuxt/ui/components/Button.vue'
import UModal from '@nuxt/ui/components/Modal.vue'
import DefectCapture from './DefectCapture.vue'
import ProjectExtras from './ProjectExtras.vue'
import {SUP,effectiveSource,loadSupplements} from './supplements'
import {fmtMoney,fmtQty,fmtNumber} from '../frame/ai-protocol'
import type {Row,Scope,Workspace} from '../frame/types'
import {S,rs,rowId,text,num,costOf,productByCode,stateLabel,inspect,linked,openProduct,scopeKey,fmtDate,api,navigate} from '../frame/store'
// 第七批 ③：BOM 依据与工艺路线叠加第五批「Cretas 补充」（只补黑湖没返回的，黑湖有值以黑湖为准），补充出来的标「Cretas 补充」
onMounted(()=>{if(!SUP.loaded)loadSupplements()})
const effRes=computed(()=>S.source?effectiveSource(S.source).resources:null)
const erows=(k:string):Row[]=>(effRes.value?.[k]||rs(k))
const follow=ref(false),followScope=ref<Scope>(),followNote=ref(''),followStatus=ref('MISSING'),followVersion=ref(0),saving=ref(false),err=ref('')
const kind=computed(()=>S.detail.kind),current=computed(()=>S.detail.row)
const chosenProject=computed(()=>kind.value==='project'?current.value:kind.value==='output'||kind.value==='task'?rs('project').find(p=>String(p.id)===String(current.value?.projectId)):['process','bom'].includes(kind.value)&&S.detail.chainProjectId?rs('project').find(p=>String(p.id)===S.detail.chainProjectId):undefined)
const chosenCode=computed(()=>kind.value==='product'?current.value?.productCode:kind.value==='bom'?current.value?.lastProductCode:chosenProject.value?.productCode),chosenProduct=computed(()=>productByCode(chosenCode.value)),chosenCost=computed(()=>chosenProject.value?costOf(chosenProject.value.id):undefined)
const chosenTasks=computed(()=>kind.value==='task'&&current.value?[current.value]:kind.value==='process'?rs('task').filter(t=>String(t.processId)===String(current.value?.id)&&(!S.detail.chainProjectId||String(t.projectId)===S.detail.chainProjectId)):chosenProject.value?rs('task').filter(t=>String(t.projectId)===String(chosenProject.value?.id)):[])
const chosenReports=computed(()=>chosenProject.value?rs('output').filter(o=>String(o.projectId)===String(chosenProject.value?.id)&&(kind.value!=='task'||String(o.taskId)===String(current.value?.id))):[])
const chosenOrders=computed(()=>kind.value==='product'&&productByCode(current.value?.productCode)?rs('project').filter(p=>p.productCode===current.value?.productCode):[])
const chosenBoms=computed(()=>kind.value==='process'?erows('bom').filter(b=>b.feedProcessCode===current.value?.code&&(!chosenProject.value||b.lastProductCode===chosenProject.value.productCode)):erows('bom').filter(b=>b.lastProductCode===chosenCode.value))
const effProduct=computed(()=>erows('product').find(p=>p.productCode===chosenCode.value)||chosenProduct.value)
const chosenRouting=computed(()=>effProduct.value?.prcessRoutingCode?erows('routing').find(r=>r.processRoutingCode===effProduct.value?.prcessRoutingCode):undefined),routingSteps=computed<Row[]>(()=>Array.isArray(chosenRouting.value?.processRoutingSteps)?chosenRouting.value!.processRoutingSteps as Row[]:[])
const scopeForCurrent=computed<Scope|undefined>(()=>chosenProject.value?{kind:'project',id:String(chosenProject.value.id)}:kind.value==='product'&&current.value?{kind:'product',id:rowId(current.value)}:undefined)
const kindName:Record<string,string>={project:'工单',product:'产品',output:'报工',task:'工序任务',process:'工序',bom:'BOM行'}
function openFollow(s?:Scope){if(!s||!S.workspace)return;followScope.value=s;followVersion.value=S.workspace.version;const f=S.workspace.followups[scopeKey(s)];followStatus.value=f?.status||'MISSING';followNote.value=f?.note||'';err.value='';follow.value=true}
async function saveFollow(){if(!S.source||!followScope.value)return;saving.value=true;err.value='';try{S.workspace=await api<Workspace>('/api/followup',{...followScope.value,factoryId:'LIUSHANMEN',revision:S.source.revision,expectedVersion:followVersion.value,status:followStatus.value,note:followNote.value});follow.value=false;S.notice='核对记录已保存；原始工单、BOM、成本均未改写。'}catch(e){err.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
function toCanvas(){if(chosenProject.value){S.detail.open=false;navigate('/production/process-hub',{project:String(chosenProject.value.id)})}}
function toCost(){if(chosenProject.value){S.detail.open=false;navigate('/lsm/cost',{order:String(chosenProject.value.id)})}}
const routeStep=(s:Row)=>{const p=rs('process').find(p=>p.code===s.code);if(p)linked('process',p.id);else S.notice='工序编码未在当前目录返回'}
</script>
<template>
<UModal v-model:open="S.detail.open" :title="kindName[kind]+' · '+String(current?.projectCode||current?.productName||current?.name||current?.id||'来源详情')" :ui="{content:'detail-modal'}"><template #body><div v-if="current" class="detail-body"><div class="detail-scope">LIUSHANMEN · 来源{{kindName[kind]||kind}} ID {{rowId(current)}} <span class="readonly">只读</span></div><div v-if="kind==='process'&&S.detail.chainProjectId" class="chain-context">当前工单 {{chosenProject?.projectCode}} · 仅显示本工单关联任务与BOM <UButton size="xs" color="neutral" variant="ghost" @click="S.detail.chainProjectId=''">查看此工序全部记录</UButton></div><div class="actions" v-if="scopeForCurrent"><UButton color="neutral" variant="outline" @click="openFollow(scopeForCurrent)">记录跟进</UButton><UButton v-if="chosenProject" color="neutral" variant="outline" @click="toCanvas()">在工序画布中查看</UButton><UButton v-if="chosenProject" color="neutral" variant="outline" @click="toCost()">看成本</UButton><span class="muted">要提问请用右下角「解读」，当前对象已切到这条记录。</span></div>
<div v-if="chosenProject" class="detail-summary"><h3>工单核对</h3><p class="muted source-demand" v-if="kind==='project'||chosenProject">来源需求：黑湖未返回这张工单的来源销售订单（快照里工单没有订单号、客户、交期字段），不按产品或日期猜配。</p><div class="facts-grid"><div><span>工单</span><b>{{chosenProject.projectCode}}</b></div><div><span>状态</span><b>{{stateLabel(chosenProject.status)}}</b></div><div><span>工单良品</span><b>{{fmtQty(chosenCost?.finishedGood,chosenCost?.unit)}}</b></div><div><span>单位直接成本</span><b>{{chosenCost?.unitCostAvailable?fmtMoney(chosenCost.unitIdentifiedDirectCost,{currency:'（币种待确认）'})+' / '+(chosenCost.unit||'单位未填'):'暂不计算'}}</b></div><div><span>已记录材料费</span><b>{{fmtMoney(chosenCost?.materialCost,{currency:'（币种待确认）'})}}</b></div><div><span>已记录人工费</span><b>{{fmtMoney(chosenCost?.laborCost,{currency:'（币种待确认）'})}}</b></div></div><p class="muted">金额币种待确认；人工为任务累计工资，不能叠加报工预计工资。</p><ul v-if="chosenCost?.issues.length" class="issues"><li v-for="i in chosenCost.issues" :key="i">{{i}}</li></ul><div class="actions"><UButton color="neutral" variant="outline" @click="openProduct(chosenProject.productCode)">查看产品</UButton><UButton v-if="kind!=='project'" color="neutral" variant="outline" @click="linked('project',chosenProject.id)">来源工单</UButton></div></div>
<div v-if="kind==='output'" class="detail-section"><h3>报工 → 工序任务</h3><p>审批 {{stateLabel(current.approvalStatus,true)}} · 报工良品 {{fmtQty(current.numberofgoodProducts,current.stockUnit as string)}} · 不加到工单良品中。</p><UButton v-if="rs('task').some(t=>String(t.id)===String(current?.taskId)&&String(t.projectId)===String(current?.projectId)&&String(t.processId)===String(current?.processId))" color="neutral" variant="outline" @click="linked('task',current.taskId)">查看任务</UButton><p v-else class="issues">来源任务对应关系不完整，保留未关联。</p></div><DefectCapture v-if="kind==='output'&&current" :report="current"/><ProjectExtras v-if="kind==='project'&&current" :project-id="String(current.id)" :project-code="String(current.projectCode||'')"/>
<div v-if="chosenOrders.length" class="detail-section"><h3>产品 → 生产工单 <small>{{chosenOrders.length}}</small></h3><table><thead><tr><th>工单</th><th>状态</th><th>良品 / 单位</th><th>下一步</th></tr></thead><tbody><tr v-for="p in chosenOrders" :key="rowId(p)"><td>{{p.projectCode}}</td><td>{{stateLabel(p.status)}}</td><td>{{fmtQty(p.numberofGoodProducts,p.projectUnit as string)}}</td><td><UButton size="xs" color="neutral" variant="ghost" @click="linked('project',p.id)">查看工单</UButton></td></tr></tbody></table></div>
<div v-if="chosenTasks.length" class="detail-section"><h3>工单 → 工序任务 <small>{{chosenTasks.length}}</small></h3><table><thead><tr><th>任务ID</th><th>工序</th><th>累计工时秒</th><th>累计人工</th><th>下一步</th></tr></thead><tbody><tr v-for="t in chosenTasks" :key="rowId(t)"><td>{{t.id}}</td><td>{{t.processName}}</td><td>{{fmtNumber(t.outputDurationForSecond,{digits:0})}}</td><td>{{fmtMoney(t.sumOutputSalary,{currency:'（币种待确认）'})}}</td><td><UButton size="xs" color="neutral" variant="ghost" @click="linked('process',t.processId)">查看工序</UButton><UButton size="xs" color="neutral" variant="ghost" @click="linked('project',t.projectId)">工单</UButton></td></tr></tbody></table></div>
<div v-if="chosenReports.length" class="detail-section"><h3>工单 → 逐笔报工 <small>{{chosenReports.length}}</small></h3><table><thead><tr><th>报工ID</th><th>任务ID</th><th>良品</th><th>审批</th><th>操作</th></tr></thead><tbody><tr v-for="o in chosenReports" :key="rowId(o)"><td>{{o.id}}</td><td>{{text(o.taskId)}}</td><td>{{fmtQty(o.numberofgoodProducts,o.stockUnit as string)}}</td><td>{{stateLabel(o.approvalStatus,true)}}</td><td><UButton size="xs" color="neutral" variant="ghost" @click="linked('output',o.id)">查看报工</UButton></td></tr></tbody></table></div>
<div v-if="chosenRouting" class="detail-section"><h3>产品工艺路线 · {{chosenRouting.processRoutingName}} <small v-if="chosenRouting._source==='cretas'" class="cretas-sup" title="黑湖没有返回这个产品的路线，这是第五批导入的补充，不是黑湖原值">Cretas 补充</small></h3><p class="muted">按来源路线顺序展示；当前任务对应关系以任务的工序ID为准。</p><div class="route-steps"><button v-for="s in routingSteps" :key="String(s.id)" @click="routeStep(s)"><small>{{s.seq}}</small><strong>{{s.name}}</strong><span>{{s.code}}</span></button></div></div>
<div v-if="chosenCode||kind==='process'" class="detail-section"><h3>工序 / 产品 → BOM 依据 <small>{{chosenBoms.length}}</small></h3><p class="muted">{{chosenCode?('产出编码 '+chosenCode):('工序编码 '+current.code)}} · 只按来源编码关联；BOM 不参与实际成本估算。</p><table><thead><tr><th>BOM行ID</th><th>投入产品</th><th>标准量 / 基数</th><th>工序绑定</th><th>操作</th></tr></thead><tbody><tr v-for="b in chosenBoms" :key="rowId(b)"><td>{{b.id}}</td><td>{{productByCode(b.nextProductCode)?.productName||b.nextProductCode}}<small>{{b.nextProductCode}}</small></td><td :title="'完整值 '+text(b.unitQty)+' / '+text(b.parentBaseQty)">{{fmtNumber(b.unitQty)}} / {{fmtNumber(b.parentBaseQty)}}</td><td>{{b.feedProcessCode?text(b.feedProcessCode):'待指定工序'}}<small v-if="b._feedSource==='cretas'" class="cretas-sup" title="黑湖没有指定投料工序，这是第五批导入的补充">Cretas 补充</small></td><td><UButton size="xs" color="neutral" variant="ghost" @click="inspect('bom',b)">依据</UButton><UButton v-if="productByCode(b.nextProductCode)" size="xs" color="neutral" variant="ghost" @click="openProduct(b.nextProductCode)">投入产品</UButton></td></tr><tr v-if="!chosenBoms.length"><td colspan="5">当前来源未返回此产品或工序的BOM，不生成替代配方。</td></tr></tbody></table></div>
<div v-if="chosenCost?.materialLinesDetail.length" class="detail-section"><h3>成本 → 真实领退料依据</h3><table><thead><tr><th>物料 / 单据</th><th>净耗用</th><th>源金额</th></tr></thead><tbody><tr v-for="(m,i) in chosenCost.materialLinesDetail" :key="i"><td>{{m.material}}<small>{{m.orderCode}}</small></td><td>{{fmtQty(m.netConsumption,m.unit as string)}}</td><td>{{fmtMoney(m.recognizedCost,{currency:'（币种待确认）'})}}</td></tr></tbody></table></div>
<div v-if="scopeForCurrent&&S.workspace?.followups[scopeKey(scopeForCurrent)]" class="saved-note"><h3>已保存核对</h3><p>{{S.workspace.followups[scopeKey(scopeForCurrent)].note}}</p><small>{{fmtDate(S.workspace.followups[scopeKey(scopeForCurrent)].at)}} · {{S.workspace.followups[scopeKey(scopeForCurrent)].sourceRevision===S.source?.revision?'当前来源':'旧来源依据，需重新核对'}}</small></div><details class="raw-fields"><summary>来源字段与身份</summary><dl><template v-for="(v,k) in current" :key="k"><dt>{{k}}</dt><dd>{{typeof v==='object'&&v!==null?'结构化来源字段（不在此展开）':text(v)}}</dd></template></dl></details></div></template></UModal>
<UModal v-model:open="follow" title="保存核对记录" :ui="{content:'follow-modal'}"><template #body><div class="follow-form"><p>只保存在六膳门原型，不改黑湖工单、报工、BOM或成本。</p><label>状态<select aria-label="跟进状态" v-model="followStatus"><option value="OPEN">未处理</option><option value="MISSING">待补资料</option><option value="CHECKED">已核对</option></select></label><label>核对说明<textarea aria-label="核对说明" v-model="followNote" rows="4"/></label><p>“已核对”不会消除原数据的核算阻断。</p><p v-if="err" role="alert" class="error">{{err}}</p><div class="actions"><UButton color="neutral" variant="outline" @click="follow=false">取消</UButton><UButton :loading="saving" @click="saveFollow()">确认保存</UButton></div></div></template></UModal>
</template>
<style scoped>
.cretas-sup{margin-left:6px;padding:0 6px;border-radius:999px;font-size:12px;background:var(--cs-primary-soft,#eef5fc);color:var(--cs-primary,#1b65a8)}
</style>
